use serde_json::Value;

pub fn solve(input: Value) -> Value {
    let input_vec: Vec<Value> = input.as_array().unwrap();
    let unit_price_cents = input_vec[0].as_i64().unwrap();
    let quantity = input_vec[1].as_i64().unwrap();
    let total_cents = unit_price_cents * quantity as i64;
    Value::from(total_cents)
}
